<script>
jQuery(document).ready(function(){
    var navListItems = jQuery('div.setup-panel div a'),
        allWells = jQuery('.setup-content'),
        allNextBtn = jQuery('.nextBtn');

    allNextBtn.click(function () {
        var curStep = jQuery(this).closest(".setup-content"),
            curStepBtn = curStep.attr("id"),
            nextStepWizard = jQuery('div.setup-panel div a[href="#' + curStepBtn + '"]').parent().next().children("a"),
            curInputs = curStep.find("input[type='text'],input[type='url']"),
            isValid = true;

        jQuery(".form-group").removeClass("has-error");
        for (var i = 0; i < curInputs.length; i++) {
            if (!curInputs[i].validity.valid) {
                isValid = false;
                jQuery(curInputs[i]).closest(".form-group").addClass("has-error");
            }
        }

        if (isValid) nextStepWizard.removeAttr('disabled').trigger('click');
    });

    jQuery("#but_upload").click(function(){
        var files = jQuery('#file')[0].files;        
        // Check file selected or not
        if(files.length > 0 ){
            var formElement = jQuery("#formupload")[0];
            var fd = new FormData(formElement);
            fd.append('file',files[0]);
            jQuery.ajax({
                url: "<?php echo url_for('com_interna/readFileExcel') ?>",
                type: 'post',
                data: fd,
                contentType: false,
                processData: false,
                beforeSend: function(){
                    javascript:jQuery.LoadingStructData();
                },
                success: function(response){
                    if(response != 0){
                        jQuery("#remoteupdate").html(response);
                        jQuery("#remoteupdate").show();
                        jQuery("#dataufile").val(jQuery("#fileuploadtmp").val());
                    }else{
                        jQuery("#remoteupdate").hide();
                        alert('Error al subir el archivo');
                    }
                },
                complete: function(){
                    javascript:jQuery.CloseLoadingStructData();
                },
            });
        }else{
            alert("Debe seleccionar un archivo.");
        }
    });
});
</script>